use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let matrix = input.as_array().unwrap();
    let n = matrix.len();
    let mut main_diagonal_sum = 0;
    let mut anti_diagonal_sum = 0;

    for i in 0..n {
        main_diagonal_sum += matrix[i][i];
        anti_diagonal_sum += matrix[i][n - 1 - i];
    }

    Value::Array(vec![Value::Number(serde_json::Number::from(main_diagonal_sum)), Value::Number(serde_json::Number::from(anti_diagonal_sum))])
}
